import { AxisScale } from '@visx/axis';
import { PickD3Scale } from '@visx/scale';
import { isNaN } from 'lodash-es';

import { OVERLAY_PADDING } from '../../../../../core/components/data-point/constants.js';
import { safeGet } from '../../../../../core/functions/safe-get.js';
import { sanitizeZeroValues } from '../../../../../core/functions/sanitize-zero-values.js';
import { ColorToken } from '../../../../../core/types/color-palette.js';
import { YAxisScales } from '../../../../types/state.js';
import { WeakMapDatapoints } from '../../../../types/timeseries.js';
import { getDatapointTime } from '../../../../utils/timeseries.js';
import { getYScaleByUnit } from '../../../../utils/yAxis.js';
import { isBandDataPoint } from '../../../displays/shared/functions/get-timeseries-type.js';
import { TimeseriesDataPointAllTypes } from '../../../displays/shared/types.js';

export type TimeseriesClosestPoint = {
  id: string;
  x: number;
  y: number;
  datapoint: TimeseriesDataPointAllTypes;
  color: ColorToken;
};

export const getClosestPoint = (
  xPoints: TimeseriesClosestPoint[],
  mouseY: number = 0,
) =>
  // new object needed to preserve the points sorting
  [...xPoints].sort(
    (a, b) => Math.abs(a.y - mouseY) - Math.abs(b.y - mouseY),
  )[0];

/**
 * Validates if the variant closest x point is the closest point to the mouse x
 *
 * @param variantClosestX - variant closest x point
 * @param closestX - current closest x point to the mouse
 * @param mouseX - mouse x point
 * @returns true if the variant closest x point  is the closest point to the mouse x
 */
const isCloser = (
  variantClosestX: number,
  closestX: number,
  mouseX: number,
): boolean => Math.abs(variantClosestX - mouseX) < Math.abs(closestX - mouseX);

/**
 * Given the mouse x-coordinate inside the chart, it returns the date in the x-axis
 * @param xAxisScale - given x-scale in the chart
 * @param mouseX - given mouse x-coordinate
 * @returns
 */
const getDateByMouseX = (xAxisScale: AxisScale<number>, mouseX: number) =>
  (xAxisScale as unknown as PickD3Scale<'time'>).invert(mouseX);

/**
 * Returns the closest points sorted by proximity given a series and mouse
 * coordinates within the same X coordinate as the closest point.
 */
export const findClosestPoints = (
  mouseX: number,
  mouseY: number,
  datapoints: TimeseriesDataPointAllTypes[],
  xAxisScale: AxisScale<number>,
  yAxis: YAxisScales,
  datapointsMap: WeakMapDatapoints,
): TimeseriesClosestPoint[] => {
  const date = getDateByMouseX(xAxisScale, mouseX);
  let xPoints: TimeseriesClosestPoint[] = [];
  let closestX = 0;
  let closestPoints: TimeseriesClosestPoint[] = [];
  const dateUnixTimestamp = date.getTime();
  let smallestTimeDelta = Infinity;

  for (const datapoint of datapoints) {
    const datapointMap = safeGet(datapointsMap, datapoint);
    const {
      isGap,
      color,
      value,
      y0,
      y1,
      unit,
      cumulativeValue,
      seriesId,
      start,
      end,
      center,
    } = datapointMap;
    if (isGap) {
      continue;
    }

    const datapointTimestamp = getDatapointTime(start, end, center);
    const timeDelta = Math.abs(datapointTimestamp - dateUnixTimestamp);

    if (timeDelta < smallestTimeDelta) {
      smallestTimeDelta = timeDelta;
      closestPoints = [];
    }

    if (timeDelta === smallestTimeDelta) {
      const yScale: AxisScale<number> = getYScaleByUnit(unit, yAxis);

      if (isBandDataPoint(datapoint)) {
        const pointY0 = sanitizeZeroValues(yScale, y0 ?? 0);
        const pointY1 = sanitizeZeroValues(yScale, y1 ?? 0);

        closestPoints.push({
          id: seriesId,
          x: xAxisScale(getDatapointTime(start, end, center)) as number,
          y: pointY0,
          color,
          datapoint,
        });

        closestPoints.push({
          id: seriesId,
          x: xAxisScale(getDatapointTime(start, end, center)) as number,
          y: pointY1,
          color,
          datapoint,
        });

        continue;
      }

      const y = sanitizeZeroValues(
        yScale,
        cumulativeValue ? cumulativeValue : value ?? 0,
      );

      if (!isNaN(y)) {
        closestPoints.push({
          id: seriesId,
          x: xAxisScale(getDatapointTime(start, end, center)) as number,
          y,
          color,
          datapoint,
        });
      }
    }
  }

  if (closestPoints[0]) {
    const variantClosestX = closestPoints[0].x;

    if (isCloser(variantClosestX, closestX, mouseX)) {
      xPoints = [...closestPoints];
      closestX = variantClosestX;
    } else if (variantClosestX === closestX) {
      xPoints.push(...closestPoints);
    }
  }

  return xPoints;
};

/**
 * Filters the data points that would fall outside the charts, but inside the overlays area
 * @param overlaysHeight
 */
export const filterOutOfBounds =
  (overlaysHeight: number) => (datapoint: TimeseriesClosestPoint) =>
    datapoint.y >= OVERLAY_PADDING &&
    datapoint.y <= overlaysHeight - OVERLAY_PADDING;
